/* Learn: who opens a program, its rich description, and covers for modules and lessons (round 33), run after parts 74 and 102. A program in a community's Learn gets `access_mode`, the creator's choice of who opens it (free for every member, from a level, bought once, a number of days after joining, or only the members picked), `member_ids`, the members picked for a private program (up to 1,000 account ids, read and written by the server only, since community_courses is server only since part 81), and `description`, the program's description as the cleaned HTML the product editor's rich text field writes (pictures, emoji, formatting; summary keeps the plain text for the cards). A course module and a course lesson each get `cover_url`, a picture from Storelib's own storage. All columns are new and empty or default, so no existing row changes meaning: a row with no access_mode is read as before, from its price, level and drip days. Until it runs, programs keep the three earlier choices and the plain description, and covers cannot be set. Safe to run again. */
DO $do$ BEGIN IF to_regclass('public.community_courses') IS NULL OR NOT EXISTS (SELECT 1 FROM information_schema.columns WHERE table_schema = 'public' AND table_name = 'community_courses' AND column_name = 'id') THEN RAISE NOTICE 'learn access: community_courses has no id yet, run part 102 first.'; RETURN; END IF; ALTER TABLE public.community_courses ADD COLUMN IF NOT EXISTS access_mode text; ALTER TABLE public.community_courses ADD COLUMN IF NOT EXISTS member_ids uuid[] NOT NULL DEFAULT '{}'::uuid[]; ALTER TABLE public.community_courses ADD COLUMN IF NOT EXISTS description text; IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname = 'community_courses_access_mode_check' AND conrelid = 'public.community_courses'::regclass) THEN ALTER TABLE public.community_courses ADD CONSTRAINT community_courses_access_mode_check CHECK (access_mode IS NULL OR access_mode IN ('free', 'level', 'paid', 'time', 'private')); END IF; IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname = 'community_courses_member_ids_check' AND conrelid = 'public.community_courses'::regclass) THEN ALTER TABLE public.community_courses ADD CONSTRAINT community_courses_member_ids_check CHECK (cardinality(member_ids) <= 1000); END IF; IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname = 'community_courses_description_length' AND conrelid = 'public.community_courses'::regclass) THEN ALTER TABLE public.community_courses ADD CONSTRAINT community_courses_description_length CHECK (description IS NULL OR char_length(description) <= 60000); END IF; END $do$;
DO $do$ BEGIN IF to_regclass('public.course_modules') IS NULL OR to_regclass('public.course_lessons') IS NULL THEN RAISE NOTICE 'learn covers: there are no course modules and lessons, run part 74 first.'; RETURN; END IF; ALTER TABLE public.course_modules ADD COLUMN IF NOT EXISTS cover_url text; ALTER TABLE public.course_lessons ADD COLUMN IF NOT EXISTS cover_url text; IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname = 'course_modules_cover_url_length' AND conrelid = 'public.course_modules'::regclass) THEN ALTER TABLE public.course_modules ADD CONSTRAINT course_modules_cover_url_length CHECK (cover_url IS NULL OR (char_length(cover_url) <= 1000 AND cover_url LIKE 'https://%')); END IF; IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname = 'course_lessons_cover_url_length' AND conrelid = 'public.course_lessons'::regclass) THEN ALTER TABLE public.course_lessons ADD CONSTRAINT course_lessons_cover_url_length CHECK (cover_url IS NULL OR (char_length(cover_url) <= 1000 AND cover_url LIKE 'https://%')); END IF; END $do$;
notify pgrst, 'reload schema';
